            Long timer = activeTimer.value();
            if (timer != null) {
                context.timerService().deleteEventTimeTimer(timer);
            }

            current += 1;
            currentStageCount.update(current);

            long nextTimer = marker.timestamp + sessionGapMillis;
            context.timerService().registerEventTimeTimer(nextTimer);
            activeTimer.update(nextTimer);
