", "new_str": "package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.SerializableTimestampAssigner;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.KeyedProcessFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    private static final int TASK_SUBMIT = 0;
    private static final int JOB_FINISH = 4;

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final long sessionGapMicros = params.getLong("sesssize", 600) * 1_000_000L;

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        WatermarkStrategy<TaskEvent> taskWatermarks = WatermarkStrategy
                .<TaskEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))
                .withTimestampAssigner(new SerializableTimestampAssigner<TaskEvent>() {
                    @Override
                    public long extractTimestamp(TaskEvent element, long recordTimestamp) {
                        return element.timestamp;
                    }
                });

        WatermarkStrategy<JobEvent> jobWatermarks = WatermarkStrategy
                .<JobEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))
                .withTimestampAssigner(new SerializableTimestampAssigner<JobEvent>() {
                    @Override
                    public long extractTimestamp(JobEvent element, long recordTimestamp) {
                        return element.timestamp;
                    }
                });

        DataStream<JobMarker> taskStream = env
                .addSource(taskSourceOrTest(new TaskEventSource(taskInput)))
                .assignTimestampsAndWatermarks(taskWatermarks)
                .filter(event -> event.eventType == TASK_SUBMIT)
                .map((MapFunction<TaskEvent, JobMarker>) event -> new JobMarker(event.jobId, event.timestamp, false));

        DataStream<JobMarker> jobStream = env
                .addSource(jobSourceOrTest(new JobEventSource(jobInput)))
                .assignTimestampsAndWatermarks(jobWatermarks)
                .filter(event -> event.eventType == JOB_FINISH)
                .map((MapFunction<JobEvent, JobMarker>) event -> new JobMarker(event.jobId, event.timestamp, true));

        taskStream
                .union(jobStream)
                .keyBy(marker -> marker.jobId)
                .process(new LongestStageProcessFunction(sessionGapMicros))
                .writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE)
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    public static class JobMarker {
        public long jobId;
        public long timestamp;
        public boolean jobFinished;

        public JobMarker() {
        }

        public JobMarker(long jobId, long timestamp, boolean jobFinished) {
            this.jobId = jobId;
            this.timestamp = timestamp;
            this.jobFinished = jobFinished;
        }
    }

    public static class LongestStageProcessFunction extends KeyedProcessFunction<Long, JobMarker, Tuple2<Long, Integer>> {

        private final long sessionGapMicros;

        private transient ValueState<Long> lastSubmitTimestamp;
        private transient ValueState<Integer> currentStageCount;
        private transient ValueState<Integer> maxStageCount;

        public LongestStageProcessFunction(long sessionGapMicros) {
            this.sessionGapMicros = sessionGapMicros;
        }

        @Override
        public void open(Configuration parameters) {
            lastSubmitTimestamp = getRuntimeContext().getState(new ValueStateDescriptor<>("lastSubmitTimestamp", Long.class));
            currentStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("currentStageCount", Integer.class));
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Integer.class));
        }

        @Override
        public void processElement(JobMarker marker, Context context, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (marker.jobFinished) {
                Integer current = currentStageCount.value();
                Integer max = maxStageCount.value();

                if (current != null) {
                    max = max == null ? current : Math.max(max, current);
                }

                out.collect(Tuple2.of(marker.jobId, max == null ? 0 : max));

                lastSubmitTimestamp.clear();
                currentStageCount.clear();
                maxStageCount.clear();
                return;
            }

            Long lastTimestamp = lastSubmitTimestamp.value();
            Integer current = currentStageCount.value();
            Integer max = maxStageCount.value();

            if (current == null) {
                current = 0;
            }

            if (lastTimestamp == null || marker.timestamp - lastTimestamp > sessionGapMicros) {
                if (max == null) {
                    max = current;
                } else {
                    max = Math.max(max, current);
                }
                current = 1;
            } else {
                current += 1;
            }

            lastSubmitTimestamp.update(marker.timestamp);
            currentStageCount.update(current);
            maxStageCount.update(max);
        }
    }

    public static class TaskEventSource implements org.apache.flink.streaming.api.functions.source.SourceFunction<TaskEvent> {

        private final String path;
        private volatile boolean running = true;

        public TaskEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (BufferedReader reader = openReader(path)) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    String[] fields = line.split(",", -1);
                    if (fields.length < 6 || fields[0].isEmpty() || fields[2].isEmpty() || fields[5].isEmpty()) {
                        continue;
                    }

                    ctx.collect(new TaskEvent(
                            Long.parseLong(fields[0]),
                            Long.parseLong(fields[2]),
                            Integer.parseInt(fields[5])
                    ));
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    public static class JobEventSource implements org.apache.flink.streaming.api.functions.source.SourceFunction<JobEvent> {

        private final String path;
        private volatile boolean running = true;

        public JobEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (BufferedReader reader = openReader(path)) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    String[] fields = line.split(",", -1);
                    if (fields.length < 4 || fields[0].isEmpty() || fields[2].isEmpty() || fields[3].isEmpty()) {
                        continue;
                    }

                    ctx.collect(new JobEvent(
                            Long.parseLong(fields[0]),
                            Long.parseLong(fields[2]),
                            Integer.parseInt(fields[3])
                    ));
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static BufferedReader openReader(String path) throws IOException {
        return new BufferedReader(
                new InputStreamReader(
                        new GZIPInputStream(new FileInputStream(path)),
                        StandardCharsets.UTF_8
                )
        );
    }
}
