                .<JobEvent>forMonotonousTimestamps()
                .withTimestampAssigner(new SerializableTimestampAssigner<JobEvent>() {
                    @Override
                    public long extractTimestamp(JobEvent element, long recordTimestamp) {
                        return element.timestamp;
                    }
                });

        DataStream<TaskEvent> taskSubmits = env
                .addSource(taskSourceOrTest(new TaskEventSource(taskInput)))
                .assignTimestampsAndWatermarks(taskWatermarks)
                .filter(event -> event.eventType == TASK_SUBMIT);

        DataStream<Tuple2<Long, Integer>> sessionCounts = taskSubmits
                .keyBy(event -> event.jobId)
                .window(EventTimeSessionWindows.withGap(Time.milliseconds(sessionGapMillis)))
                .aggregate(new CountAgg(), new SessionCountWindowFunction());

        DataStream<Long> finishedJobs = env
                .addSource(jobSourceOrTest(new JobEventSource(jobInput)))
                .assignTimestampsAndWatermarks(jobWatermarks)
                .filter(event -> event.eventType == JOB_FINISH)
                .map((MapFunction<JobEvent, Long>) event -> event.jobId);

        DataStream<Tuple2<Long, Integer>> longestStagePerFinishedJob = sessionCounts
                .keyBy(value -> value.f0)
                .connect(finishedJobs.keyBy(id -> id))
                .process(new EmitResultOnEnd());

        longestStagePerFinishedJob
                .writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE)
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    public static class CountAgg implements AggregateFunction<TaskEvent, Integer, Integer> {

        @Override
        public Integer createAccumulator() {
            return 0;
        }

        @Override
        public Integer add(TaskEvent value, Integer accumulator) {
            return accumulator + 1;
        }

        @Override
        public Integer getResult(Integer accumulator) {
            return accumulator;
        }

        @Override
        public Integer merge(Integer a, Integer b) {
            return a + b;
        }
    }

    public static class SessionCountWindowFunction extends ProcessWindowFunction<Integer, Tuple2<Long, Integer>, Long, TimeWindow> {

        @Override
        public void process(Long key, Context context, Iterable<Integer> elements, Collector<Tuple2<Long, Integer>> out) {
            Integer count = elements.iterator().next();
            out.collect(Tuple2.of(key, count));
        }
    }

    public static class EmitResultOnEnd extends KeyedCoProcessFunction<Long, Tuple2<Long, Integer>, Long, Tuple2<Long, Integer>> {

        private transient ValueState<Integer> maxStageCount;
        private transient ValueState<Boolean> finished;
        private transient ValueState<Boolean> endTimerRegistered;

        @Override
        public void open(Configuration parameters) {
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Integer.class));
            finished = getRuntimeContext().getState(new ValueStateDescriptor<>("finished", Boolean.class));
            endTimerRegistered = getRuntimeContext().getState(new ValueStateDescriptor<>("endTimerRegistered", Boolean.class));
        }

        @Override
        public void processElement1(Tuple2<Long, Integer> value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Integer currentMax = maxStageCount.value();
            if (currentMax == null || value.f1 > currentMax) {
                maxStageCount.update(value.f1);
            }
            registerEndTimer(ctx);
        }

        @Override
        public void processElement2(Long value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            finished.update(true);
            registerEndTimer(ctx);
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Boolean isFinished = finished.value();
            if (isFinished != null && isFinished) {
                Integer max = maxStageCount.value();
                out.collect(Tuple2.of(ctx.getCurrentKey(), max == null ? 0 : max));
            }
            clearState();
        }

        private void registerEndTimer(Context ctx) throws Exception {
            Boolean registered = endTimerRegistered.value();
            if (registered == null || !registered) {
                ctx.timerService().registerEventTimeTimer(Long.MAX_VALUE);
                endTimerRegistered.update(true);
            }
        }

        private void clearState() {
            maxStageCount.clear();
            finished.clear();
            endTimerRegistered.clear();
        }
    }

    public static class TaskEventSource implements org.apache.flink.streaming.api.functions.source.SourceFunction<TaskEvent> {

        private final String path;
        private volatile boolean running = true;

        public TaskEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (BufferedReader reader = openReader(path)) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    String[] fields = line.split(",", -1);
                    if (fields.length < 6 || fields[0].isEmpty() || fields[2].isEmpty() || fields[5].isEmpty()) {
                        continue;
                    }

                    ctx.collect(new TaskEvent(
                            Long.parseLong(fields[0]) / 1000L,
                            Long.parseLong(fields[2]),
                            Integer.parseInt(fields[5])
                    ));
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    public static class JobEventSource implements org.apache.flink.streaming.api.functions.source.SourceFunction<JobEvent> {

        private final String path;
        private volatile boolean running = true;

        public JobEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (BufferedReader reader = openReader(path)) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    String[] fields = line.split(",", -1);
                    if (fields.length < 4 || fields[0].isEmpty() || fields[2].isEmpty() || fields[3].isEmpty()) {
                        continue;
                    }

                    ctx.collect(new JobEvent(
                            Long.parseLong(fields[0]) / 1000L,
                            Long.parseLong(fields[2]),
                            Integer.parseInt(fields[3])
                    ));
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static BufferedReader openReader(String path) throws IOException {
        return new BufferedReader(
                new InputStreamReader(
                        new GZIPInputStream(new FileInputStream(path)),
                        StandardCharsets.UTF_8
                )
        );
    }
}
