                    max = current;
                } else {
                    max = Math.max(max, current);
                }
                maxStageCount.update(max);
            }

            currentStageCount.clear();
            activeTimer.clear();
        }

        private void clearState() throws Exception {
            currentStageCount.clear();
            maxStageCount.clear();
            activeTimer.clear();
        }
