        private transient ValueState<Long> activeTimer;

        public LongestStageProcessFunction(long sessionGapMillis) {
            this.sessionGapMillis = sessionGapMillis;
        }

        @Override
        public void open(Configuration parameters) {
            currentStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("currentStageCount", Integer.class));
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Integer.class));
            activeTimer = getRuntimeContext().getState(new ValueStateDescriptor<>("activeTimer", Long.class));
        }

        @Override
        public void processElement(JobMarker marker, Context context, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Integer current = currentStageCount.value();
            Integer max = maxStageCount.value();

            if (current == null) {
                current = 0;
            }

            if (max == null) {
                max = 0;
            }

            if (marker.jobFinished) {
                max = Math.max(max, current);
                out.collect(Tuple2.of(marker.jobId, max));
                clearState();
                return;
            }

            Long timer = activeTimer.value();
            if (timer != null) {
                context.timerService().deleteEventTimeTimer(timer);
            }

            current += 1;
            currentStageCount.update(current);

            long nextTimer = marker.timestamp + sessionGapMillis;
            context.timerService().registerEventTimeTimer(nextTimer);
            activeTimer.update(nextTimer);
        }

